#!/usr/bin/env python3
"""Writes the generated file lists and checks the codebase map for drift.

    python3 tools/codebase_map.py           rewrite each area's generated file list
    python3 tools/codebase_map.py --check   exit 1 if anything has drifted (CI runs this)

docs/codebase-map.md is written by hand and stays small: the areas, their entry points, the
"go here for X" routing table and what to update together. The structural layer is
generated into each area's own CLAUDE.md (`src/sim/CLAUDE.md`, `tests/CLAUDE.md`,
`data/CLAUDE.md`, ...), between the GENERATED markers: every source, test and tool file with
the first sentence of its header comment (a GDScript file's leading `##` lines, a Python
file's docstring), so a file's description lives in the file itself and a session only
reads the list for the area it works in.

--check fails when:
  - an area's file list is stale (a file was added, moved, renamed or its header changed:
    run this script and commit the result),
  - an area (a directory under src/, or tests, tools, data) has no CLAUDE.md,
  - a path written in backticks in the map or a CLAUDE.md no longer exists,
  - a top-level area (a directory under src/ or data/, or a top-level directory) isn't
    named in docs/codebase-map.md.

Standard library only, so CI needs nothing but python3.
"""

import glob
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
MAP = os.path.join(ROOT, "docs", "codebase-map.md")
BEGIN = "<!-- GENERATED by tools/codebase_map.py: don't edit by hand -->"
END = "<!-- END GENERATED -->"
TOP_DIRS = ["src", "data", "tests", "tools", "docs", "assets", "scenes"]
MAX_DESC = 120
MIN_DESC = 60


def rel(p):
    return os.path.relpath(p, ROOT).replace(os.sep, "/")


def first_sentence(text):
    """The opening of a header: whole sentences until there's enough to say what the file
    is (a bare "Cosmetic effects." says too little), cut at MAX_DESC characters."""
    text = " ".join(text.split())
    out = ""
    for m in re.finditer(r".*?(?<=[^\s.])[.!?](?=\s|$)|.+$", text):
        out = (out + " " + m.group(0).strip()).strip()
        if len(out) >= MIN_DESC:
            break
    if len(out) > MAX_DESC:
        out = out[: MAX_DESC - 1].rstrip() + "…"
    return out


def gd_header(path):
    """class_name and the leading ## comment of a GDScript file."""
    cls = ""
    doc = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            s = line.strip()
            if s.startswith("class_name "):
                cls = s.split()[1]
            elif s.startswith("##"):
                doc.append(s[2:].strip())
            elif s == "" and not doc:
                continue
            elif s.startswith(("extends ", "@tool", "@icon")) and not doc:
                continue
            elif doc:
                break
            elif s.startswith("#"):
                continue
            else:
                break
    return cls, first_sentence(" ".join(doc))


def py_header(path):
    with open(path, encoding="utf-8") as f:
        src = f.read()
    m = re.search(r'^(?:#![^\n]*\n)?\s*(?:"""|\'\'\')(.*?)(?:"""|\'\'\')', src, re.S)
    return first_sentence(m.group(1).split("\n\n")[0]) if m else ""


def shader_header(path):
    doc = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            s = line.strip()
            if s.startswith("//"):
                doc.append(s.lstrip("/ "))
            elif doc or (s and not s.startswith("shader_type")):
                break
    return first_sentence(" ".join(doc))


def file_lines(d):
    """One line per source, test or tool file in `d`: name, class_name, header sentence."""
    out = []
    files = sorted(
        p for p in glob.glob(os.path.join(ROOT, d, "*"))
        if os.path.isfile(p) and os.path.splitext(p)[1] in (".gd", ".py", ".gdshader")
    )
    for p in files:
        ext = os.path.splitext(p)[1]
        cls = ""
        if ext == ".gd":
            cls, desc = gd_header(p)
        elif ext == ".py":
            desc = py_header(p)
        else:
            desc = shader_header(p)
        name = "`%s`" % os.path.basename(p)
        if cls:
            name += " (%s)" % cls
        out.append("- %s — %s" % (name, desc or "(no header comment)"))
    return out


def data_lines():
    out = []
    for d in sorted(glob.glob(os.path.join(ROOT, "data", "*"))):
        if os.path.isdir(d):
            ids = sorted(os.path.splitext(os.path.basename(p))[0] for p in glob.glob(os.path.join(d, "*.json")))
            out.append("- `%s/` — %s" % (os.path.basename(d), ", ".join(ids)))
        elif d.endswith(".json"):
            out.append("- `%s`" % os.path.basename(d))
    return out


def index_areas():
    """The directories whose CLAUDE.md carries a generated file list."""
    areas = [rel(d) for d in sorted(glob.glob(os.path.join(ROOT, "src", "*"))) if os.path.isdir(d)]
    return areas + ["tests", "tools", "data"]


def render(text, area):
    """`text` (an area's CLAUDE.md) with its generated file list brought up to date; a file
    without the markers gets a "Files" section appended."""
    lines = data_lines() if area == "data" else file_lines(area)
    block = BEGIN + "\n" + "\n".join(lines) + "\n" + END
    if BEGIN in text and END in text:
        head, rest = text.split(BEGIN, 1)
        return head + block + rest.split(END, 1)[1]
    return text.rstrip("\n") + "\n\n## Files\n\n" + block + "\n"


def hand_written(text):
    """Everything outside the generated block."""
    if BEGIN in text and END in text:
        head, rest = text.split(BEGIN, 1)
        return head + rest.split(END, 1)[1]
    return text


def path_exists(token):
    """A backticked token that looks like a repo path: does it (or its glob) exist?"""
    p = token.split(":", 1)[0]
    p = re.sub(r"<[^>]+>", "*", p).rstrip("/")
    return bool(glob.glob(os.path.join(ROOT, p)))


def looks_like_path(token):
    if " " in token or "/" not in token or token.startswith(("res://", "user://", "http", "--")):
        return False
    return token.split("/", 1)[0] in TOP_DIRS + [".github"]


def read(path):
    with open(path, encoding="utf-8") as f:
        return f.read()


def check():
    problems = []
    # Each area's generated file list.
    for area in index_areas():
        path = os.path.join(ROOT, area, "CLAUDE.md")
        if not os.path.isfile(path):
            problems.append("`%s/` has no CLAUDE.md (its notes, gotchas and file list go there)" % area)
            continue
        text = read(path)
        if render(text, area) != text:
            problems.append("`%s/CLAUDE.md`'s file list is stale: run `python3 tools/codebase_map.py`" % area)
    # Paths written by hand, in the map and every CLAUDE.md.
    docs = [MAP, os.path.join(ROOT, "CLAUDE.md")] + [os.path.join(ROOT, a, "CLAUDE.md") for a in index_areas()]
    for doc in docs:
        if not os.path.isfile(doc):
            continue
        for token in sorted(set(re.findall(r"`([^`\n]+)`", hand_written(read(doc))))):
            if looks_like_path(token) and not path_exists(token):
                problems.append("`%s` names a path that no longer exists: `%s`" % (rel(doc), token))
    # Every top-level area is routed in the map.
    named = set(t.rstrip("/") for t in re.findall(r"`([^`\n]+)`", read(MAP)))
    areas = [d for d in TOP_DIRS if os.path.isdir(os.path.join(ROOT, d))]
    for parent in ("src", "data"):
        areas += [rel(d) for d in sorted(glob.glob(os.path.join(ROOT, parent, "*"))) if os.path.isdir(d)]
    for a in areas:
        if a not in named:
            problems.append("a top-level area isn't in docs/codebase-map.md: `%s/`" % a)
    return problems


def main():
    if "--check" in sys.argv:
        problems = check()
        for p in problems:
            print("codebase map: " + p)
        if problems:
            print("See CLAUDE.md, \"Workflow\": update the map in the same change.")
            sys.exit(1)
        print("codebase map: up to date")
        return
    changed = 0
    for area in index_areas():
        path = os.path.join(ROOT, area, "CLAUDE.md")
        if not os.path.isfile(path):
            print("codebase map: `%s/` has no CLAUDE.md; write one (rules, gotchas) and run again" % area)
            continue
        text = read(path)
        new = render(text, area)
        if new != text:
            with open(path, "w", encoding="utf-8", newline="\n") as f:
                f.write(new)
            changed += 1
            print("codebase map: rewrote the file list in %s/CLAUDE.md" % area)
    if not changed:
        print("codebase map: already up to date")


if __name__ == "__main__":
    main()
